char **fullJustify(char **words, int wordsSize, int maxWidth, int *returnSize) {
  char **res = (char **)malloc(sizeof(char *) * wordsSize);
  *returnSize = 0;
  int i = 0;
  while (i < wordsSize) {
    int j = i, len = 0;
    while (j < wordsSize && len + (int)strlen(words[j]) + (j - i) <= maxWidth) {
      len += strlen(words[j]);
      j++;
    }
    int count = j - i;
    char *line = (char *)malloc(maxWidth + 1);
    int pos = 0;
    if (j == wordsSize || count == 1) {
      for (int k = i; k < j; k++) {
        int l = strlen(words[k]);
        memcpy(line + pos, words[k], l);
        pos += l;
        if (k != j - 1) line[pos++] = ' ';
      }
      while (pos < maxWidth) line[pos++] = ' ';
    } else {
      int totalChars = 0;
      for (int k = i; k < j; k++) totalChars += strlen(words[k]);
      int gaps = count - 1;
      int spaces = maxWidth - totalChars;
      int base = spaces / gaps;
      int extra = spaces % gaps;
      for (int k = i; k < j; k++) {
        int l = strlen(words[k]);
        memcpy(line + pos, words[k], l);
        pos += l;
        if (k != j - 1) {
          int sp = base + (k - i < extra ? 1 : 0);
          for (int t = 0; t < sp; t++) line[pos++] = ' ';
        }
      }
    }
    line[maxWidth] = '\0';
    res[(*returnSize)++] = line;
    i = j;
  }
  return res;
}

class Solution {
public:
  vector<string> fullJustify(vector<string> &words, int maxWidth) {
    vector<string> res;
    int i = 0, n = words.size();
    while (i < n) {
      int j = i, len = 0;
      while (j < n && len + (int)words[j].size() + (j - i) <= maxWidth) {
        len += words[j].size();
        j++;
      }
      int count = j - i;
      string line;
      if (j == n || count == 1) {
        for (int k = i; k < j; k++) {
          if (k > i) line += ' ';
          line += words[k];
        }
        line += string(maxWidth - line.size(), ' ');
      } else {
        int totalChars = 0;
        for (int k = i; k < j; k++) totalChars += words[k].size();
        int gaps = count - 1;
        int spaces = maxWidth - totalChars;
        int base = spaces / gaps, extra = spaces % gaps;
        for (int k = i; k < j; k++) {
          line += words[k];
          if (k != j - 1) {
            int sp = base + (k - i < extra ? 1 : 0);
            line += string(sp, ' ');
          }
        }
      }
      res.push_back(line);
      i = j;
    }
    return res;
  }
};

func fullJustify(words []string, maxWidth int) []string {
	var res []string
	i, n := 0, len(words)
	for i < n {
		j, length := i, 0
		for j < n && length+len(words[j])+(j-i) <= maxWidth {
			length += len(words[j])
			j++
		}
		count := j - i
		var line strings.Builder
		if j == n || count == 1 {
			for k := i; k < j; k++ {
				if k > i {
					line.WriteByte(' ')
				}
				line.WriteString(words[k])
			}
			for line.Len() < maxWidth {
				line.WriteByte(' ')
			}
		} else {
			total := 0
			for k := i; k < j; k++ {
				total += len(words[k])
			}
			gaps := count - 1
			spaces := maxWidth - total
			base, extra := spaces/gaps, spaces%gaps
			for k := i; k < j; k++ {
				line.WriteString(words[k])
				if k != j-1 {
					sp := base
					if k-i < extra {
						sp++
					}
					line.WriteString(strings.Repeat(" ", sp))
				}
			}
		}
		res = append(res, line.String())
		i = j
	}
	return res
}

class Solution {
  public List<String> fullJustify(String[] words, int maxWidth) {
    List<String> res = new ArrayList<>();
    int i = 0, n = words.length;
    while (i < n) {
      int j = i, len = 0;
      while (j < n && len + words[j].length() + (j - i) <= maxWidth) {
        len += words[j].length();
        j++;
      }
      int count = j - i;
      StringBuilder line = new StringBuilder();
      if (j == n || count == 1) {
        for (int k = i; k < j; k++) {
          if (k > i) line.append(' ');
          line.append(words[k]);
        }
        while (line.length() < maxWidth) line.append(' ');
      } else {
        int totalChars = 0;
        for (int k = i; k < j; k++) totalChars += words[k].length();
        int gaps = count - 1;
        int spaces = maxWidth - totalChars;
        int base = spaces / gaps, extra = spaces % gaps;
        for (int k = i; k < j; k++) {
          line.append(words[k]);
          if (k != j - 1) {
            int sp = base + (k - i < extra ? 1 : 0);
            for (int t = 0; t < sp; t++) line.append(' ');
          }
        }
      }
      res.add(line.toString());
      i = j;
    }
    return res;
  }
}

class Solution:
    def fullJustify(self, words: List[str], maxWidth: int) -> List[str]:
        res = []
        i, n = 0, len(words)
        while i < n:
            j, length = i, 0
            while j < n and length + len(words[j]) + (j - i) <= maxWidth:
                length += len(words[j])
                j += 1
            count = j - i
            if j == n or count == 1:
                line = " ".join(words[i:j])
                line += " " * (maxWidth - len(line))
            else:
                total = sum(len(w) for w in words[i:j])
                gaps = count - 1
                base, extra = divmod(maxWidth - total, gaps)
                parts = []
                for k in range(i, j):
                    parts.append(words[k])
                    if k != j - 1:
                        parts.append(" " * (base + (1 if k - i < extra else 0)))
                line = "".join(parts)
            res.append(line)
            i = j
        return res

impl Solution {
  pub fn full_justify(words: Vec<String>, max_width: i32) -> Vec<String> {
    let max_width = max_width as usize;
    let mut res = vec![];
    let n = words.len();
    let mut i = 0;
    while i < n {
      let mut j = i;
      let mut length = 0;
      while j < n && length + words[j].len() + (j - i) <= max_width {
        length += words[j].len();
        j += 1;
      }
      let count = j - i;
      let line: String;
      if j == n || count == 1 {
        let mut l = words[i..j].join(" ");
        l.push_str(&" ".repeat(max_width - l.len()));
        line = l;
      } else {
        let total: usize = words[i..j].iter().map(|w| w.len()).sum();
        let gaps = count - 1;
        let spaces = max_width - total;
        let base = spaces / gaps;
        let extra = spaces % gaps;
        let mut parts: Vec<String> = vec![];
        for k in i..j {
          parts.push(words[k].clone());
          if k != j - 1 {
            let sp = base + if k - i < extra { 1 } else { 0 };
            parts.push(" ".repeat(sp));
          }
        }
        line = parts.join("");
      }
      res.push(line);
      i = j;
    }
    res
  }
}

const fullJustify = (words: string[], maxWidth: number): string[] => {
  const res: string[] = [];
  const n = words.length;
  let i = 0;
  while (i < n) {
    let j = i;
    let length = 0;
    while (j < n && length + words[j].length + (j - i) <= maxWidth) {
      length += words[j].length;
      j++;
    }
    const count = j - i;
    let line: string;
    if (j === n || count === 1) {
      line = words.slice(i, j).join(' ');
      line += ' '.repeat(maxWidth - line.length);
    } else {
      let total = 0;
      for (let k = i; k < j; k++) total += words[k].length;
      const gaps = count - 1;
      const spaces = maxWidth - total;
      const base = Math.floor(spaces / gaps);
      const extra = spaces % gaps;
      let parts = '';
      for (let k = i; k < j; k++) {
        parts += words[k];
        if (k !== j - 1) {
          parts += ' '.repeat(base + (k - i < extra ? 1 : 0));
        }
      }
      line = parts;
    }
    res.push(line);
    i = j;
  }
  return res;
};
